CREATE TABLE plataforma_landing (
 id BIGINT PRIMARY KEY AUTO_INCREMENT,
 slug VARCHAR(80) NOT NULL UNIQUE,
 publicado BOOLEAN NOT NULL DEFAULT FALSE,
 contenido JSON NOT NULL,
 version BIGINT NOT NULL DEFAULT 0
);
INSERT INTO plataforma_permiso(codigo,nombre,descripcion) VALUES
 ('PLATAFORMA_MARKETING_GESTIONAR','Gestionar landing pages','Contenido comercial de Fluora');
INSERT INTO plataforma_rol_permiso(rol_id,permiso_id)
 SELECT r.id,p.id FROM plataforma_rol r CROSS JOIN plataforma_permiso p
 WHERE r.codigo='ADMINISTRADOR_PLATAFORMA' AND p.codigo='PLATAFORMA_MARKETING_GESTIONAR';
